{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "weaken",
  "supportive_card_ids": ["C04", "C14", "C15", "C25", "C28", "C30", "C38", "C56", "C53"],
  "contradictory_card_ids": ["C67", "C69", "C72", "C76"],
  "prediction_basis_card_ids": ["C04", "C14", "C15", "C30", "C38", "C56"],
  "claims": [
    {
      "claim": "Direct absolute oral bioavailability values for piperazine or heteroaromatic comparators exceed the 20% threshold: GSK1322322 77% fed and 57% fasted (C04, C15), brigatinib 46% (C14), and piperazine-containing TDP223206 rat F 24.46% at 50 mg/kg and 32.95% at 10 mg/kg (C25, C28).",
      "card_ids": ["C04", "C14", "C15", "C25", "C28"]
    },
    {
      "claim": "SHR6390, the query or its closest analog, shows substantial oral systemic exposure after single 150 mg doses: fasted geometric-mean Cmax 52.2 ng/mL (C38), fed Cmax 81.8 ng/mL (C33), and monotherapy AUC0-inf 2140 h·ng/mL (C30), supporting meaningful oral absorption.",
      "card_ids": ["C30", "C33", "C38"]
    },
    {
      "claim": "Same-class ribociclib shows high Caco-2 absorptive permeability (Papp A→B 135 nm/s) with low efflux ratio 1.3 (C56, C64), supporting adequate intestinal absorption for the piperazine and cyclopentyl CDK4/6 chemotype.",
      "card_ids": ["C56", "C64"]
    },
    {
      "claim": "L6 hepatic clearance evidence for the close analog ribociclib shows moderate HLM intrinsic clearance (23.4 to 26.4 µL/mg/min, C67, C74) with dominant CYP3A4 metabolism (C69, C72) and an expected high first-pass effect (C76), indicating some presystemic loss but not establishing F below 20%.",
      "card_ids": ["C67", "C69", "C72", "C74", "C76"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "contradictory",
      "decision_effect": "weakened",
      "card_ids": ["C67", "C69", "C72", "C74", "C76"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself is present.",
    "No IV or oral AUC comparison is available for the query or close analogs; L3 AUC and Cmax records lack an IV comparator and cannot directly establish F >= 20%.",
    "L6 hepatic clearance records are for ribociclib and ON 123300, not the query directly; rat microsomal data (C66, C70, C71, C73, C75) have limited human transferability.",
    "No query-specific hepatic clearance or metabolic stability experiment is supplied.",
    "The magnitude of first-pass loss for the query cannot be quantified from the moderate ribociclib CLint values."
  ],
  "decision_summary": "Predicted high: F >= 20% is better supported. Direct absolute-F values above threshold for piperazine or heteroaromatic comparators (46 to 77%), rat F above 20% for a piperazine analog, substantial oral exposure for SHR6390, and high permeability with low efflux for same-class ribociclib support adequate oral absorption. L6 hepatic clearance evidence for the close analog ribociclib indicates moderate CYP3A4-mediated first-pass metabolism, which tempers but does not overturn the high prediction; no affirmative evidence establishes F below 20%."
}

